<template><WPCard class="wp-word-card" :data-density="entryLevel<=2?'foundation':entryLevel===3?'balanced':'independent'"><view class="word-content" :class="{'word-wide':!conceal&&word.word.length>8}"><view class="word-core"><text class="eyebrow">{{word.pos}} · {{word.unit}}</text><WPPhonicsWord v-if="!conceal&&phonics" :word="word.word" :phonics="phonics" :active-chunk-index="activeChunkIndex" :playback-state="playbackState"/><text v-else class="word">{{conceal?'···':word.word}}</text><text class="ipa" v-if="!conceal&&entryLevel>=3">{{word.ipa}}</text></view><view v-if="(showMeaning!==false && !conceal) || revealMeaning || promptPicture" class="word-definition"><image v-if="(!conceal||promptPicture)&&word.image&&!imageFailed" class="word-picture" :src="word.image" mode="aspectFit" :alt="word.meaning" @error="imageFailed=true"/><view v-else-if="!conceal||promptPicture" class="word-illustration" aria-hidden="true">{{wordIllustrations[word.id]||'📖'}}</view><text v-if="!promptPicture" class="meaning">{{word.meaning}}</text></view><view class="word-extra"><slot /></view></view></WPCard></template>
<script setup lang="ts">
import WPCard from '../wp-card/WPCard.vue'
import {wordIllustrations} from './illustrations'
import WPPhonicsWord from '../phonics/WPPhonicsWord.vue'
import type {PhonicsData,PhonicsPlaybackState} from '../../../packages/phonics'
import {ref,watch} from 'vue'
import type {Word} from '../../../packages/core_learning';const props=withDefaults(defineProps<{word:Word;entryLevel?:number;promptPicture?:boolean;conceal?:boolean;revealMeaning?:boolean;showMeaning?:boolean;phonics?:PhonicsData;activeChunkIndex?:number|null;playbackState?:PhonicsPlaybackState}>(),{entryLevel:3})
const imageFailed=ref(false);watch(()=>props.word.id,()=>{imageFailed.value=false})
</script>
<style scoped>.word-content{min-height:200px;text-align:center;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px}.word-core,.word-definition,.word-extra{display:flex;flex-direction:column;align-items:center;gap:8px;min-width:0}.word-extra{max-width:100%}.word{font-size:var(--wp-font-word);line-height:1.15;font-weight:var(--wp-weight-display);letter-spacing:-1px;overflow-wrap:anywhere}.word-illustration{font-size:40px;line-height:1.3;padding:8px 16px;background:var(--wp-surface-tonal);border-radius:var(--wp-radius)}.ipa{color:var(--wp-muted-foreground);font-size:var(--wp-font-body-large)}.meaning{font-size:22px;font-weight:var(--wp-weight-medium)}.eyebrow{font-size:var(--wp-font-caption);color:var(--wp-muted-foreground)}</style>
